export class ModalTransportistaCtrl{static $inject=["$http","$uibModalInstance","mainService","formulario","params"];constructor($http,$uibModalInstance,_mS,_form,_params){this.$http=$http,this.$uibModalInstance=$uibModalInstance,this._mS=_mS,this._form=_form,this._params=_params,this.tipoRegistro=1,this.data={}}$onInit(){this.getTipoIdentificacion()}getTipoIdentificacion(){this.$http.get("/TipoIdentificacion/GetByType?tipo=V").then(({data:response})=>{"0"!==response.id?(this.tipoIdentificaciones=response.data,this.data.idTipoIdentificacion=response.data[0].idTipoIdentificacion,this._params&&(this.tipoRegistro=2,this.data=this._params)):toastr.warning(response.message)})}validarTipoIdentificacion(idTipo){let{codigoIdentificacion:codigoIdentificacion}=this.tipoIdentificaciones.find(val=>val.idTipoIdentificacion===idTipo)||{codigoIdentificacion:0};return codigoIdentificacion}saveUpdate(){let tituloToast=1===this.tipoRegistro?"Guardar":"Actualizar";if(this._form.campo(this.data.idTipoIdentificacion))return void toastr.warning("Seleccione el Tipo de Identificación",tituloToast);if(this._form.campo(this.data.nroIdentificacion))return void toastr.warning("Ingrese N° de Identificación",tituloToast);if("C"===this.validarTipoIdentificacion(this.data.idTipoIdentificacion)&&10!==this.data.nroIdentificacion.length)return void toastr.warning("Número de Cédula tiene que tener 10 dígitos",tituloToast);if("R"===this.validarTipoIdentificacion(this.data.idTipoIdentificacion)&&13!==this.data.nroIdentificacion.length)return void toastr.warning("Número de RUC tiene que tener 13 dígitos",tituloToast);if(this._form.campo(this.data.nombre))return void toastr.warning("Ingrese el Nombre",tituloToast);let url=1==this.tipoRegistro?"/Transportista/Post":"/Transportista/Put?id="+this.data.idTransportista,method=1===this.tipoRegistro?"post":"put";this._mS.getData(method,url,this.data).then(response=>{console.log(response),"0"!==response.id&&"0"!==response.code?"1"!==response.id&&"1"!==response.code||(toastr.success(response.message),this.$uibModalInstance.close(response)):toastr.warning(response.message)})}closeModal(){this.$uibModalInstance.close()}}